def is_valid_iso_datetime(s):
    if s.count('T') != 1:
        return False
    date_part, time_part = s.split('T')
    dparts = date_part.split('-')
    if len(dparts) != 3:
        return False
    y, mo, d = dparts
    if not (len(y) == 4 and y.isdigit() and len(mo) == 2 and mo.isdigit() and len(d) == 2 and d.isdigit()):
        return False
    try:
        dt.date(int(y), int(mo), int(d))
    except ValueError:
        return False
    tparts = time_part.split(':')
    if len(tparts) != 3:
        return False
    h, mi, sec = tparts
    if not (len(h) == 2 and h.isdigit() and len(mi) == 2 and mi.isdigit() and len(sec) == 2 and sec.isdigit()):
        return False
    h, mi, sec = int(h), int(mi), int(sec)
    return 0 <= h <= 23 and 0 <= mi <= 59 and 0 <= sec <= 59

