def is_valid_date_range(start, end):
    def parse(s):
        parts = s.split('-')
        if len(parts) != 3:
            return None
        y, mo, d = parts
        if not (len(y) == 4 and y.isdigit() and len(mo) == 2 and mo.isdigit() and len(d) == 2 and d.isdigit()):
            return None
        try:
            return dt.date(int(y), int(mo), int(d))
        except ValueError:
            return None
    d1 = parse(start)
    d2 = parse(end)
    if d1 is None or d2 is None:
        return False
    return d1 <= d2

