def is_valid_duration_string(s):
    if not s:
        return False
    pattern = re.compile(r'^(?:(0|[1-9]\d*)h)?(?:(0|[1-9]\d*)m)?(?:(0|[1-9]\d*)s)?$')
    m = pattern.fullmatch(s)
    if not m:
        return False
    if not any(g is not None for g in m.groups()):
        return False
    return True

