def is_valid_base64_format(s):
    if len(s) == 0 or len(s) % 4 != 0:
        return False
    pad_count = 0
    i = len(s) - 1
    while i >= 0 and s[i] == '=':
        pad_count += 1
        i -= 1
    if pad_count > 2:
        return False
    body = s[:len(s) - pad_count]
    if '=' in body:
        return False
    allowed = set(string.ascii_letters + string.digits + '+/')
    return all(c in allowed for c in body)

