def is_valid_snake_case(s):
    if not s:
        return False
    if s[0] not in string.ascii_lowercase:
        return False
    for c in s:
        if c == '_' or c in string.digits or c in string.ascii_lowercase:
            continue
        return False
    if s.endswith('_'):
        return False
    if '__' in s:
        return False
    return True

